$runtime=json_decode(file_get_contents(dirname(__DIR__).'/.e2e/lifecycle/runtime.json'),TRUE);if(!preg_match('/^gulhouse_test_[a-zA-Z0-9_]+$/D',$runtime['schema']??''))throw new RuntimeException('Synthetic only');putenv('GULHOUSE_DATABASE='.$runtime['schema']);putenv('GULHOUSE_TEST_URL='.$runtime['url']);require __DIR__.'/http-helpers.php';$own=json_decode(file_get_contents($root.'/.e2e/lifecycle/ciko/state-private.json'),TRUE);$c=row("SELECT * FROM gh_resident_cases WHERE phone='".$db->real_escape_string($own['phone'])."'");if(!$c||strpos($c['full_name'],'CIKO Synthetic ')!==0)throw new RuntimeException('Own intake required');
try{if(!$c['stay_id']){$room=row('SELECT * FROM gh_rooms ORDER BY id LIMIT 1');unset($room['id']);$room['room_code']='CIKO-PAY-'.time();$room['room_label']='CIKO Payment dedicated';$room['status']='available';$room['is_public']=0;$keys=implode(',',array_map(function($k){return '`'.$k.'`';},array_keys($room)));$values=implode(',',array_map(function($v)use($db){return $v===NULL?'NULL':"'".$db->real_escape_string((string)$v)."'";},array_values($room)));$db->query('INSERT INTO gh_rooms('.$keys.') VALUES('.$values.')');$rid=(int)$db->insert_id;$db->query('UPDATE gh_resident_cases SET room_id='.$rid.' WHERE id='.(int)$c['id']);post('/master/index.php/login',array('username'=>$runtime['username'],'password'=>$runtime['password']),'/master/index.php/login');post('/master/index.php/lifecycle/action/'.$c['id'],array('action'=>'reserve','end_date'=>date('Y-m-d',strtotime('+1 month')),'monthly_price'=>'1500000','deposit'=>'500000'),'/master/index.php/lifecycle/detail/'.$c['id']);$c=row('SELECT * FROM gh_resident_cases WHERE id='.(int)$c['id']);}check($c['stay_id']&&$c['status']==='reserved','dedicated own CIKO case reserved with initial invoice');file_put_contents($root.'/.e2e/lifecycle/ciko/payment-state-private.json',json_encode(array('id'=>(int)$c['id'],'code'=>$own['code'],'phone'=>$own['phone'])));echo json_encode(array('synthetic_case_id'=>(int)$c['id'],'synthetic_stay_id'=>(int)$c['stay_id'])).PHP_EOL;}finally{if(is_file($cookie))unlink($cookie);}
